-- Carry the 2026-10-30 fact-check corrections that were made in src/data but
-- never reached D1, which is what the live site reads: eleven planet texts in
-- the space dataset (Sun holds about 13 lakh Earths, Olympus Mons is about two
-- and a half Everests, the Great Red Spot is at least 190 years old, and
-- others), ঝরনা in the language dataset, the nature world's intro and colour,
-- and two "পর্দায়" cues that named things the scene does not show.
-- Apply with:  npx wrangler d1 migrations apply posora --remote
--
-- Every statement is guarded on the exact seed value, so anything an admin
-- has edited since is left alone, the same rule as 0008 and 0009.

UPDATE worlds SET intro = 'সৌরজগৎ থেকে চাঁদ, তারা ও মহাকাশ অভিযান পর্যন্ত ঘুরে দেখো। গ্রহ বেছে তার তথ্য পড়ো, মডেল ঘোরাও এবং ছোট ছোট মিশনে শেখা যাচাই করো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'space' AND intro = 'রেফারেন্স স্ক্রিনটি এই ভুবনের জন্যই বানানো - বাঁয়ে গ্রহের তালিকা, মাঝে ঘূর্ণায়মান থ্রিডি গ্রহ ও চাঁদের কক্ষপথ, ডানে মাধ্যাকর্ষণ-বায়ুমণ্ডল-তাপমাত্রার পাঞ্জি। এটিই ফ্ল্যাগশিপ, বাকি নয়টি ভুবন এর কাঠামো ধার করবে।';

UPDATE worlds SET intro = 'বল ও গতি, শক্তি, আলো, শব্দ, তাপ এবং বিদ্যুৎ নিয়ে মডেল ও ব্যাখ্যা দেখো। সরল যন্ত্র ও আলোর আলাদা পরীক্ষায় নিয়ন্ত্রণ বদলে ফল পরীক্ষা করো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'physics' AND intro = 'এই ভুবনের প্রতিটি আইটেম একেকটি ছোট পরীক্ষাগার। পড়ার বদলে স্লাইডার ঘুরিয়ে ফল দেখা - ঘর্ষণ বাড়ালে গাড়ি কতদূর যায়, লেন্স সরালে ছবি কোথায় পড়ে।';

UPDATE worlds SET intro = 'পদার্থের অবস্থা, পরমাণু, মৌল, বিক্রিয়া আর রান্নাঘরের রসায়ন ধাপে ধাপে দেখো। পর্যায় সারণির মৌলে চাপলে তার পরিচয় ও ব্যবহার পড়তে পারো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'chemistry' AND intro = 'পর্যায় সারণি এখানে ঠিক সেই “ক্লিক করে প্রতিটি জিনিস শেখা” কাঠামোর নিখুঁত উদাহরণ - ১১৮টি ঘর, প্রতিটিতে ক্লিক করলে মাঝে ঘূর্ণায়মান পরমাণু, ডানে ধর্মের পাঞ্জি।';

UPDATE worlds SET intro = 'গাছের অংশ ও জীবনচক্র, বাংলাদেশের গাছপালা ও প্রাণী এবং মানবদেহের বিষয়গুলো দৃশ্য ও ব্যাখ্যার সঙ্গে অনুসন্ধান করো। মডেলে অংশ বেছে কাছে থেকে দেখো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'life' AND intro = 'এখানে হিরো মডেল স্তরে স্তরে খোলা যায় - গাছের পাতা সরিয়ে শিরা, মানুষের চামড়া সরিয়ে পেশি, তারপর কঙ্কাল। বাংলাদেশের চেনা গাছ ও প্রাণী দিয়ে শুরু, তারপর বিশ্ব।';

UPDATE worlds SET hue = '#1D7777', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'nature' AND hue = '#2A9E9E';

UPDATE worlds SET intro = 'আবহাওয়া থেকে বাস্তুতন্ত্র - আটটি জীবন্ত থ্রিডি ভূদৃশ্যে পুরো দৃশ্য দেখো, বিষয়ের কাছে যাও, তারপর খুঁটিনাটি আলাদা করে আবিষ্কার করো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'nature' AND intro = 'ভুবনটির হিরো একটি ইন্টারঅ্যাকটিভ বাংলাদেশ - অঞ্চলে ক্লিক করলে সেখানকার ভূমিরূপ, নদী, বন ও ঋতুর চেহারা। ছয় ঋতুর চাকা ঘোরালে গোটা দৃশ্যপট বদলায়।';

UPDATE worlds SET intro = 'খাদ্যের উপাদান, সুষম থালা, খাবারের উৎস ও নিরাপদ অভ্যাস নিয়ে খেলতে খেলতে শেখো। থালার আলাদা খেলায় খাবার সাজিয়ে ভারসাম্য দেখো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'food' AND intro = 'হিরো এখানে একটি খালি থালা। শিশু টেনে টেনে খাবার সাজায়, আর ডান পাশের পুষ্টি-মিটার সঙ্গে সঙ্গে বলে দেয় কী কম পড়ল। খাবারের উৎসে ক্লিক করলে খেত থেকে থালা পর্যন্ত যাত্রা।';

UPDATE worlds
SET cats_json = json_set(cats_json, '$[0].play', 'খাবারের নানা উপাদান এবার টেবিলে দেখো: ভাত, মাছ, তেল, ফল, লবণ, পানি ও আঁশের উদাহরণ। স্লাইডার টানলে একেকটি খাবার সামনে আসে।'),
    updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'food'
  AND json_extract(cats_json, '$[0].n') = 'খাদ্যের ছয় উপাদান'
  AND json_extract(cats_json, '$[0].play') = 'ছয় উপাদানের প্রতিটি তার নিজের চেহারায় - শর্করার ভাত, আমিষের মাছ, স্নেহের তেল, ভিটামিনের ফল, খনিজের লবণ, আর এক গ্লাস পানি। স্লাইডার টানলে একেকটা সামনে আসে।';

UPDATE worlds SET intro = 'সংখ্যা, চার প্রক্রিয়া, ভগ্নাংশ, জ্যামিতি ও পরিমাপ নিয়ে মডেল, উদাহরণ আর খেলা আছে। আকার ও মাপের আলাদা পরীক্ষায় নিজে মান বদলে ফল দেখো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'math' AND intro = 'গণিতে হিরো হলো ম্যানিপুলেটিভ - সংখ্যারেখা, অ্যাবাকাসের গুটি, কাটা যায় এমন পিৎজা, টাকা-পয়সা। কোনো সমস্যা লিখে দেওয়া হয় না; জিনিস নাড়াচাড়া করেই উত্তর বেরোয়।';

UPDATE worlds SET intro = 'টাকা চেনা থেকে কেনাকাটা, সঞ্চয়, বাজেট ও ব্যাংকিং পর্যন্ত বাস্তব উদাহরণে শেখো। ছোট দোকান আর সঞ্চয়ের খেলায় হিসাব করে সিদ্ধান্ত নাও।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'money' AND intro = 'টাকা এমন একটা জিনিস যা স্কুলে শেখানো হয় না, অথচ সারা জীবন লাগে। হিরো এখানে একটি ছোট দোকান - শিশু দাম ঠিক করে, উপকরণ কেনে, দিন শেষে লাভ-ক্ষতি মেলায়। বড়দের স্তরে সেই একই দোকান হয়ে যায় বাজেট, চক্রবৃদ্ধি সুদ আর এক পাতার বিজনেস প্ল্যান।';

UPDATE worlds SET intro = 'বর্ণ, শব্দ, বাক্য আর গল্পের সঙ্গে পরিচিত হও। অক্ষর ও হাতের লেখা অনুশীলনের আলাদা পাতায় দেখে দেখে লিখতে পারো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'language' AND intro = 'বর্ণমালার গ্রিডই এই ভুবনের হিরো - ৫০টি ঘর, প্রতিটিতে ক্লিক করলে উচ্চারণ বাজে, লেখার ক্রম অ্যানিমেট হয়, একটি শব্দ ও ছবি আসে। যুক্তবর্ণের জন্য আলাদা অ্যাসেম্বলি অ্যানিমেশন - বাংলা শেখার সবচেয়ে বড় বাধা এটিই।';

UPDATE worlds SET intro = 'আবেগ চেনা, বন্ধুত্ব, নিরাপত্তা ও একসঙ্গে থাকার বিষয়গুলো পরিস্থিতি ও ছোট মিশনে ভাবো। নিজের সিদ্ধান্তের কারণ ব্যাখ্যা করার সুযোগও আছে।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'social' AND intro = 'এখানে কোনো তথ্য মুখস্থ করানো নেই। হিরো একটি পরিস্থিতি-কার্ড: “তোমার বন্ধু তোমার খাতা ছিঁড়ে ফেলেছে - তুমি কী করবে?” তিনটি পথ, প্রতিটির ফল দেখানো হয়, তারপর ফিরে গিয়ে অন্য পথও চেষ্টা করা যায়।';

UPDATE worlds SET intro = 'আবিষ্কার, বিজ্ঞানী, পরিমাপের যন্ত্র, ঘরের পরীক্ষা আর পৃথিবীর গঠন নিয়ে জানো। নিরাপদ পরীক্ষাগুলো বড়দের সঙ্গে করে কী বদলাচ্ছে তা লক্ষ করো।', updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'discovery' AND intro = 'এই ভুবনটি বাকি নয়টিকে জুড়ে দেয় - বিজ্ঞান কীভাবে করা হয়, কারা করেছেন, আর ঘরে বসে নিজে কী কী করা যায়। প্রতিটি পরীক্ষার কার্ডে উপকরণ, ধাপ, সতর্কতা ও “কী লক্ষ করবে”।';

UPDATE worlds
SET cats_json = json_set(cats_json, '$[6].play', 'থার্মোমিটার, দাঁড়িপাল্লা, রুলার, মাপার ফিতা, মাইক্রোস্কোপ, দূরবীন, কম্পাস ও ঘড়ি - প্রতিটি যন্ত্র আলাদা। স্লাইডার টানলে একেকটা সামনে আসে।'),
    updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE slug = 'discovery'
  AND json_extract(cats_json, '$[6].n') = 'পরিমাপের যন্ত্র'
  AND json_extract(cats_json, '$[6].play') = 'থার্মোমিটার, দাঁড়িপাল্লা, স্কেল, মাইক্রোস্কোপ, দূরবীন, কম্পাস, ঘড়ি - প্রতিটি যন্ত্র তার নিজের চেহারায়। স্লাইডার টানলে একেকটা সামনে আসে।';

UPDATE datasets
SET json = json_set(json, '$[0].l1', 'সূর্য একটা বিশাল আগুনের বল - আসলে একটা তারা! এটা এত বড় যে এর ভেতরে ১৩ লাখ পৃথিবী ঢুকে যাবে। সূর্যের আলো আর তাপ না থাকলে পৃথিবীতে কোনো গাছ, প্রাণী বা মানুষ থাকত না।'), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE key = 'space'
  AND json_extract(json, '$[0].id') = 'sun'
  AND json_extract(json, '$[0].l1') = 'সূর্য একটা বিশাল আগুনের বল - আসলে একটা তারা! এটা এত বড় যে এর ভেতরে ১০ লাখ পৃথিবী ঢুকে যাবে। সূর্যের আলো আর তাপ না থাকলে পৃথিবীতে কোনো গাছ, প্রাণী বা মানুষ থাকত না।';

UPDATE datasets
SET json = json_set(json, '$[1].l3', 'বুধের কক্ষপথ সবচেয়ে উৎকেন্দ্রিক (e = ০.২০৬), আর এর অনুসূর বিন্দুর অগ্রগমন নিউটনীয় গণনা থেকে প্রতি শতাব্দীতে ৪৩ আর্ক-সেকেন্ড বেশি - যা আইনস্টাইনের সাধারণ আপেক্ষিকতার প্রথম পরীক্ষামূলক প্রমাণ। বুধের লোহার কেন্দ্র গ্রহটির ব্যাসার্ধের ৮৫% - সম্ভবত প্রাচীন কোনো সংঘর্ষে বাইরের স্তর উড়ে গিয়েছিল। মেসেঞ্জার (২০১১–১৫) অভিযান এটি নিয়ে গবেষণা করেছে, আর বেপিকলম্বো ২০২৬-এর নভেম্বরে বুধের কক্ষপথে পৌঁছানোর কথা।'), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE key = 'space'
  AND json_extract(json, '$[1].id') = 'mercury'
  AND json_extract(json, '$[1].l3') = 'বুধের কক্ষপথ সবচেয়ে উৎকেন্দ্রিক (e = ০.২০৬), আর এর অনুসূর বিন্দুর অগ্রগমন নিউটনীয় গণনা থেকে প্রতি শতাব্দীতে ৪৩ আর্ক-সেকেন্ড বেশি - যা আইনস্টাইনের সাধারণ আপেক্ষিকতার প্রথম পরীক্ষামূলক প্রমাণ। বুধের লোহার কেন্দ্র গ্রহটির ব্যাসার্ধের ৮৫% - সম্ভবত প্রাচীন কোনো সংঘর্ষে বাইরের স্তর উড়ে গিয়েছিল। মেসেঞ্জার (২০১১–১৫) ও বেপিকলম্বো (২০২৫–) অভিযান এটি নিয়ে গবেষণা করছে।';

UPDATE datasets
