WHERE key = 'space'
  AND json_extract(json, '$[7].id') = 'saturn'
  AND json_extract(json, '$[7].l3') = 'শনির বলয় সম্ভবত মাত্র ১০–১০০ কোটি বছর পুরোনো - কোনো বরফের চাঁদ রশ সীমার ভেতরে ঢুকে জোয়ার-বলে ভেঙে গিয়েছিল। ক্যাসিনি (২০০৪–১৭) দেখায় বলয়ের উপাদান ধীরে ধীরে গ্রহে "বলয়-বৃষ্টি" হয়ে ঝরছে; আনুমানিক ১০ কোটি বছরে বলয় মিলিয়ে যাবে। এনসেলাডাসের দক্ষিণ মেরু থেকে পানির ফোয়ারা বেরোয়, যাতে জৈব অণু পাওয়া গেছে - জীবন খোঁজার অন্যতম লক্ষ্য। শনির উত্তর মেরুতে একটি ষড়ভুজাকার জেট স্ট্রিম আছে, যার প্রতিটি বাহু পৃথিবীর চেয়ে বড়।';

UPDATE datasets
SET json = json_set(json, '$[8].l2', 'ইউরেনাস ৯৮° হেলে আছে - সম্ভবত প্রাচীন কোনো বড় সংঘর্ষে এটি কাত হয়ে গিয়েছিল। ফলে এর প্রতিটি মেরুতে ৪২ বছর দিন, তারপর ৪২ বছর রাত। বায়ুমণ্ডলে মিথেন গ্যাস লাল আলো শুষে নেয় বলে গ্রহটি নীলচে-সবুজ দেখায়। ইউরেনাসেরও ১৩টি পাতলা বলয় আছে, আর এর বায়ুমণ্ডল সৌরজগতের গ্রহদের মধ্যে সবচেয়ে ঠান্ডা - কোথাও কোথাও −২২৪ °C পর্যন্ত নামে।'), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE key = 'space'
  AND json_extract(json, '$[8].id') = 'uranus'
  AND json_extract(json, '$[8].l2') = 'ইউরেনাস ৯৮° হেলে আছে - সম্ভবত প্রাচীন কোনো বড় সংঘর্ষে এটি কাত হয়ে গিয়েছিল। ফলে এর প্রতিটি মেরুতে ৪২ বছর দিন, তারপর ৪২ বছর রাত। বায়ুমণ্ডলে মিথেন গ্যাস লাল আলো শুষে নেয় বলে গ্রহটি নীলচে-সবুজ দেখায়। ইউরেনাসেরও ১৩টি পাতলা বলয় আছে, আর এটি সৌরজগতের সবচেয়ে ঠান্ডা গ্রহ।';

UPDATE datasets
SET json = json_set(json, '$[8].l3', 'ইউরেনাসের ভেতরে পানি, অ্যামোনিয়া ও মিথেনের "বরফ" (আসলে গরম ঘন তরল) - তাই "বরফ দানব"। এর চৌম্বক ক্ষেত্র ঘূর্ণন অক্ষ থেকে ৫৯° হেলে আছে ও কেন্দ্রছাড়া, যা এখনো রহস্য। ভয়েজার-২ (১৯৮৬) একমাত্র অভিযান যা কাছ দিয়ে গেছে; ২০২২-এর মার্কিন দশকীয় জরিপ ইউরেনাস অরবিটারকে সর্বোচ্চ অগ্রাধিকার দিয়েছে। মডেল বলছে এর ভেতরে চাপে মিথেন ভেঙে হীরার বৃষ্টি হতে পারে।'), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE key = 'space'
  AND json_extract(json, '$[8].id') = 'uranus'
  AND json_extract(json, '$[8].l3') = 'ইউরেনাসের ভেতরে পানি, অ্যামোনিয়া ও মিথেনের "বরফ" (আসলে গরম ঘন তরল) - তাই "বরফ দানব"। এর চৌম্বক ক্ষেত্র ঘূর্ণন অক্ষ থেকে ৫৯° হেলে আছে ও কেন্দ্রছাড়া, যা এখনো রহস্য। ভয়েজার-২ (১৯৮৬) একমাত্র অভিযান যা কাছ দিয়ে গেছে; ২০২৩-এর মার্কিন দশকীয় জরিপ ইউরেনাস অরবিটারকে সর্বোচ্চ অগ্রাধিকার দিয়েছে। মডেল বলছে এর ভেতরে চাপে মিথেন ভেঙে হীরার বৃষ্টি হতে পারে।';

UPDATE datasets
SET json = json_set(json, '$.consonants[8].word', 'ঝরনা'), updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE key = 'language'
  AND json_extract(json, '$.consonants[8].ch') = 'ঝ'
  AND json_extract(json, '$.consonants[8].word') = 'ঝর্ণা';
